create or replace function public.hash_treasure_box_activation_pin(p_pin text)
returns text language sql immutable set search_path='' as $$ select encode(extensions.digest(convert_to(upper(p_pin),'UTF8'),'sha256'::text),'hex'); $$;
create or replace function public.admin_provision_physical_treasure_box(p_edition text default null) returns table(physical_box_id uuid,box_id text,activation_pin text,nfc_public_token uuid,nfc_path text) language plpgsql security definer set search_path='' as $$ declare v_id uuid:=gen_random_uuid(); v_serial text:=public.format_physical_treasure_box_serial(nextval('public.physical_treasure_box_serial_seq')); v_pin text:=public.generate_treasure_box_activation_pin(); v_nfc uuid:=gen_random_uuid(); begin if not public.is_legacy_link_admin() then raise exception 'Admin access required'; end if; insert into public.physical_treasure_boxes(id,serial_code,edition,claim_status,activation_pin_hash,activation_pin_last4,pin_generated_at,nfc_public_token,provisioned_at,setup_status) values(v_id,v_serial,p_edition,'unclaimed',public.hash_treasure_box_activation_pin(v_pin),right(v_pin,4),now(),v_nfc,now(),'not_started'); return query select v_id,v_serial,v_pin,v_nfc,'/n/'||v_nfc::text; end; $$;
create or replace function public.claim_physical_treasure_box_by_pin(p_nfc_public_token uuid,p_activation_pin text) returns table(physical_box_id uuid,box_id text,was_claimed boolean,setup_status text) language plpgsql security definer set search_path='' as $$ declare v_box public.physical_treasure_boxes%rowtype; v_pin text; begin if auth.uid() is null then raise exception 'Authentication required'; end if; v_pin:=upper(regexp_replace(coalesce(p_activation_pin,''),'[^A-Z0-9]','','g')); if length(v_pin)<>6 then raise exception 'Enter the 6-character activation PIN'; end if; select * into v_box from public.physical_treasure_boxes where nfc_public_token=p_nfc_public_token for update; if v_box.id is null then raise exception 'Treasure box not found'; end if; if v_box.owner_id is not null then if v_box.owner_id=auth.uid() then return query select v_box.id,v_box.serial_code,false,v_box.setup_status; return; end if; raise exception 'Treasure box already claimed'; end if; if v_box.claim_status<>'unclaimed' then raise exception 'Treasure box is not available to claim'; end if; if v_box.activation_pin_hash is null or public.hash_treasure_box_activation_pin(v_pin)<>v_box.activation_pin_hash then raise exception 'Activation PIN does not match this Treasure Box'; end if; update public.physical_treasure_boxes set owner_id=auth.uid(),claim_status='claimed',claimed_at=now(),pin_consumed_at=now(),setup_status='in_progress',updated_at=now() where id=v_box.id; return query select v_box.id,v_box.serial_code,true,'in_progress'::text; end; $$;